@Test
    public void testUpdateFlowRule() throws Exception {
        String path = "/gateway/flow/save.json";

        // Add one entity into memory repository for update
        GatewayFlowRuleEntity addEntity = new GatewayFlowRuleEntity();
        addEntity.setId(1L);
