static boolean containsUnescapedChars(String s, char[] targets) {
        boolean escaped = false;

        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);

            if (c == '\\' && !escaped) {
                escaped = true;
            } else {
                if (!escaped) {
                    for (int j = 0; j < targets.length; j++) {
                        if (c == targets[j]) {
                            return true;
                        }
                    }
                }
                escaped = false;
            }
        }

        return false;
    }

