			"<log4j:properties>\n" +
			"<log4j:data name=\"key1\" value=\"value1\"/>\n" +
			"<log4j:data name=\"key2\" value=\"value2\"/>\n" +
			"</log4j:properties>\n" +
			"</log4j:event>";

		LoggingEvent readEvent = read(eventString);
		logEvent(readEvent);

