public double getDeratedMultiplier(double distance) {
        if (distance < this.radius){
            // e^( ln(m) * (r - d) / r)
            return Math.exp( Math.log(minimumDeratingValue) * ((radius - distance) / radius ) );
        }
        return 1.0;
    }

