                    }
                    createPTVProgram();
                    buildPlaceholderRows();
                    subscriber.onNext(ptvProgram);
                    subscriber.onCompleted();
                } catch (LMISException e) {
                    subscriber.onError(e);
                }
            }
        }).observeOn(AndroidSchedulers.mainThread()).subscribeOn(Schedulers.io());
    }

