                gridP.y = coord.y == gridDim.height ? (int)coord.y-1 : (int)coord.y;

                cov.evaluate(gridP, covValue);
                int value = Integer.valueOf((String)feature.getAttribute("value"));
                assertEquals(covValue[0], value);
            }
        }
    }

