                fileTo = fileFrom + "_V3.0.0.xml";
                success = transformXmlData(fileFrom, fileTo, "data/xslt/V2.1.2-to-V3.0.0.xsl");
                appliedTransformations.add("V2.1.2-to-V3.0.0.xsl");
